<?php
require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../services/TicketService.php';Auth::requireLogin();if(!TicketService::canManage()&&!Auth::can('ticketing.settings','edit')){http_response_code(403);exit('دسترسی تنظیمات تیکت فعال نیست.');}if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!Auth::verifyCsrf($_POST['_csrf']??null))throw new DomainException('اعتبار فرم منقضی شده است.');$category=(int)($_POST['category_id']??0)?:null;$priority=in_array($_POST['priority']??'',array_keys(TicketService::PRIORITIES),true)?$_POST['priority']:'normal';Database::execute('INSERT INTO ticket_sla_rules(category_id,priority,first_response_minutes,resolution_minutes,active,created_at,updated_at) VALUES(?,?,?,?,?,NOW(),NOW()) ON DUPLICATE KEY UPDATE first_response_minutes=VALUES(first_response_minutes),resolution_minutes=VALUES(resolution_minutes),active=VALUES(active),updated_at=NOW()',[$category,$priority,max(1,(int)$_POST['first_response_minutes']),max(1,(int)$_POST['resolution_minutes']),isset($_POST['active'])?1:0]);flash('قاعده SLA ذخیره شد.');}catch(Throwable $e){error_log('Ticket SLA: '.$e->getMessage());flash('ذخیره SLA انجام نشد.','danger');}redirect('/admin/ticket-settings.php');}$categories=TicketService::categories(false);$rows=Database::fetchAll('SELECT s.*,c.title category_title FROM ticket_sla_rules s LEFT JOIN ticket_categories c ON c.id=s.category_id ORDER BY c.title,s.priority');$pageTitle='تنظیمات تیکتینگ';require __DIR__.'/../views/partials/admin-header.php';?>
<div class="section-heading-row"><div><h1>تنظیمات SLA تیکتینگ</h1><p class="muted">زمان‌ها بر حسب دقیقه و بدون وابستگی به Messenger</p></div><a class="btn" href="/admin/tickets.php">بازگشت</a></div><section class="card admin-form"><form method="post"><input type="hidden" name="_csrf" value="<?=e(Auth::csrfToken())?>"><div class="grid grid-3"><label>دسته<select name="category_id"><option value="">همه دسته‌ها</option><?php foreach($categories as $category):?><option value="<?=$category['id']?>"><?=e($category['title'])?></option><?php endforeach?></select></label><label>اولویت<select name="priority"><?php foreach(TicketService::PRIORITIES as $key=>$label):?><option value="<?=$key?>"><?=e($label)?></option><?php endforeach?></select></label><label>اولین پاسخ<input type="number" name="first_response_minutes" min="1" value="480"></label><label>حل کامل<input type="number" name="resolution_minutes" min="1" value="2880"></label><label><input type="checkbox" name="active" checked> فعال</label></div><button class="btn btn-primary">ذخیره SLA</button></form></section><section class="card"><div class="table-wrap"><table><thead><tr><th>دسته</th><th>اولویت</th><th>اولین پاسخ</th><th>حل</th><th>فعال</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=e($row['category_title']?:'همه')?></td><td><?=e(TicketService::PRIORITIES[$row['priority']]??$row['priority'])?></td><td><?=format_number($row['first_response_minutes'])?> دقیقه</td><td><?=format_number($row['resolution_minutes'])?> دقیقه</td><td><?=$row['active']?'بله':'خیر'?></td></tr><?php endforeach?></tbody></table></div></section><?php require __DIR__.'/../views/partials/admin-footer.php';?>
